; memmap.asm -- chapter 3: every address, written and read back
; generated by gen03.py
        INCLUDE "msx.inc"
        OUTPUT "memmap.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
counts  EQU VARS + 16           ; 64 counts of 2 bytes, one for each kilobyte
total   EQU VARS + 12           ; all the addresses that kept a write
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, counts
        ld b, 128
.zero:  ld (hl), 0
        inc hl
        djnz .zero
test_start:
        call memtest
test_end:
        ld b, 1
        ld c, 0
        ld hl, t_head
        call puts
        ld ix, counts
        ld hl, 0
        ld (total), hl
        ld b, 3
        xor a                   ; the page
page:   push af
        ld c, 0
        call hexdig             ; the page number
        ld c, 2
        ld a, '$'
        call putc
        inc c
        pop af
        push af
        rrca
        rrca                    ; page x $40: the high byte of its first address
        call puthex
        xor a
        call puthex
        ld c, 8
        ld hl, 0                ; the page's count
        ld e, 16                ; sixteen kilobytes
kb:     push de
        ld e, (ix+0)
        ld d, (ix+1)
        add hl, de
        ld a, d
        or e
        ld a, 1                 ; no address of the kilobyte kept a write
        jr z, .put
        ld a, d
        cp 4                    ; 1,024 = $0400: all of them did
        ld a, 2
        jr z, .put
        ld a, '?'               ; some did: the program says it cannot tell
.put:   call putc
        inc c
        inc ix
        inc ix
        pop de
        dec e
        jr nz, kb
        push hl
        ld de, (total)
        add hl, de
        ld (total), hl
        pop hl
        ld c, 25
        call putd16
        pop af
        inc b
        inc b
        inc a
        cp 4
        jr nz, page
        ld c, 0
        ld hl, t_total
        call puts
        ld hl, (total)
        ld c, 25
        call putd16
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; memtest: every address from $0000 to $FFFF. The byte is turned over (CPL),
; written, compared, and the old byte put back at once; an address that kept
; the write adds one to the count of its kilobyte. Interrupts are off.
memtest:
        ld hl, 0
.next:  ld a, (hl)
        ld b, a                 ; B: the byte as it was
        cpl                     ; every bit turned over: certainly different
        ld (hl), a
        cp (hl)                 ; Z if the address kept it
        ld (hl), b              ; put the old byte back (LD does not touch F)
        jr nz, .skip
        push hl
        ld a, h
        rrca
        rrca                    ; H / 4: the kilobyte, 0 to 63
        and %00111111
        add a, a                ; two bytes a count
        ld e, a
        ld d, 0
        ld hl, counts
        add hl, de
        inc (hl)
        jr nz, .nc
        inc hl
        inc (hl)
.nc:    pop hl
.skip:  inc hl
        ld a, h
        or l
        jr nz, .next            ; until HL wraps round to 0
        ret

t_head: db "pg start  one box a KB    kept", 0
t_total: db "  of 65536 addresses", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putd16: HL = a number (0-65535) as five characters, right-aligned.
;         B = row, C = column; C moves on by 5. Uses A, DE, HL.
putd16: push bc
        ld de, d16buf
        ld bc, -10000
        call .digit
        ld bc, -1000
        call .digit
        ld bc, -100
        call .digit
        ld bc, -10
        call .digit
        ld a, l
        add a, '0'
        ld (de), a              ; the units, always printed
        ld hl, d16buf
        ld b, 4
.blank: ld a, (hl)              ; leading zeros become spaces
        cp '0'
        jr nz, .print
        ld (hl), ' '
        inc hl
        djnz .blank
.print: pop bc
        ld hl, d16buf
        ld e, 5
.out:   ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, .out
        ret
.digit: ld a, '0' - 1           ; how many times BC fits: subtract until it goes below
.sub:   inc a
        add hl, bc              ; BC is negative: the carry means it still fitted
        jr c, .sub
        sbc hl, bc              ; one too many: add it back (the carry is clear)
        ld (de), a
        inc de
        ret
d16buf  EQU VARS + 4            ; 5 bytes of RAM, after numbuf

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
